-- Candidate schema for synthetic PostgreSQL evaluation only.
-- Text dates/JSON retain existing representation. Integers use bigint; BLOB uses bytea.
-- Applied only by reviewed transactional migration runner.
CREATE TABLE computers(id TEXT PRIMARY KEY,name TEXT,shadow_account TEXT,ip TEXT,operator TEXT,category TEXT);
CREATE TABLE phone_devices(
        id TEXT PRIMARY KEY, name TEXT NOT NULL, state TEXT NOT NULL DEFAULT '待确认',
        state_source TEXT NOT NULL DEFAULT 'auto', owner TEXT NOT NULL DEFAULT '',
        location TEXT NOT NULL DEFAULT '', note TEXT NOT NULL DEFAULT '');
CREATE TABLE accounts(id TEXT PRIMARY KEY,computer_id TEXT REFERENCES computers(id),slot BIGINT,name TEXT,status TEXT,note TEXT,douyin_id TEXT,homepage TEXT,work_count BIGINT,last_collected TEXT, collection_state TEXT NOT NULL DEFAULT '', collection_error TEXT NOT NULL DEFAULT '', last_attempted TEXT NOT NULL DEFAULT '', account_type TEXT NOT NULL DEFAULT '待确认', parent_account_id TEXT REFERENCES accounts(id), registered_on TEXT NOT NULL DEFAULT '', auxiliary_state TEXT NOT NULL DEFAULT '待确认', lifecycle_note TEXT NOT NULL DEFAULT '', registration_phone TEXT NOT NULL DEFAULT '', card_stability TEXT NOT NULL DEFAULT '待确认', password_state TEXT NOT NULL DEFAULT '待确认', phone_device_id TEXT REFERENCES phone_devices(id), phone_device_source TEXT NOT NULL DEFAULT '', phone_device_note TEXT NOT NULL DEFAULT '', office_group TEXT NOT NULL DEFAULT '', nurture_started TEXT NOT NULL DEFAULT '',UNIQUE(computer_id,slot));
CREATE TABLE daily(account_id TEXT REFERENCES accounts(id),day TEXT,published BIGINT NOT NULL CHECK(published IN (0,1)),PRIMARY KEY(account_id,day));
-- Self-references may arrive child-first; validate the complete graph at commit.
ALTER TABLE accounts ALTER CONSTRAINT accounts_parent_account_id_fkey DEFERRABLE INITIALLY IMMEDIATE;
CREATE TABLE imports(name TEXT PRIMARY KEY);
CREATE TABLE auth_users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,username TEXT NOT NULL UNIQUE,
      name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('owner','admin','employee','viewer')),
      permissions TEXT NOT NULL DEFAULT '[]',active BIGINT NOT NULL DEFAULT 1 CHECK(active IN (0,1)),
      password_hash TEXT NOT NULL,created_at BIGINT NOT NULL);
CREATE TABLE auth_sessions(token_hash TEXT PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES auth_users(id),
      csrf TEXT NOT NULL,expires_at BIGINT NOT NULL);
CREATE TABLE auth_setup(token_hash TEXT PRIMARY KEY,expires_at BIGINT NOT NULL);
CREATE TABLE auth_limits(key TEXT PRIMARY KEY,failures BIGINT NOT NULL,expires_at BIGINT NOT NULL);
CREATE TABLE auth_audit(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,at BIGINT NOT NULL,actor_id BIGINT,
      actor_name TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL);
CREATE TABLE auth_migrations(name TEXT PRIMARY KEY);
CREATE TABLE phone_cards(
        id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, phone TEXT NOT NULL UNIQUE,
        label TEXT NOT NULL DEFAULT '', carrier TEXT NOT NULL DEFAULT '待确认',
        status TEXT NOT NULL DEFAULT '待确认', owner TEXT NOT NULL DEFAULT '',
        location TEXT NOT NULL DEFAULT '', expires_on TEXT NOT NULL DEFAULT '',
        note TEXT NOT NULL DEFAULT '', keeper TEXT NOT NULL DEFAULT '', code_contact TEXT NOT NULL DEFAULT '', code_note TEXT NOT NULL DEFAULT '', ownership TEXT NOT NULL DEFAULT '待确认', code_state TEXT NOT NULL DEFAULT '无待办', return_state TEXT NOT NULL DEFAULT '待确认', return_due TEXT NOT NULL DEFAULT '', returned_on TEXT NOT NULL DEFAULT '', source_note TEXT NOT NULL DEFAULT '');
CREATE TABLE collection_jobs(account_id TEXT PRIMARY KEY REFERENCES accounts(id), homepage TEXT NOT NULL, douyin_id TEXT NOT NULL DEFAULT '', token TEXT NOT NULL, state TEXT NOT NULL, started_at TEXT NOT NULL DEFAULT '');
CREATE TABLE collection_settings(id BIGINT PRIMARY KEY CHECK(id=1),auto_enabled BIGINT NOT NULL DEFAULT 1, paused BIGINT NOT NULL DEFAULT 0, pause_reason TEXT NOT NULL DEFAULT '');
CREATE TABLE collection_worker(id BIGINT PRIMARY KEY CHECK(id=1),seen DOUBLE PRECISION NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT '',command TEXT NOT NULL DEFAULT '');
CREATE TABLE publishing_layout(
      batch TEXT NOT NULL,computer_id TEXT NOT NULL REFERENCES computers(id),slot BIGINT NOT NULL,
      account_id TEXT REFERENCES accounts(id),label TEXT NOT NULL,office TEXT NOT NULL,
      source_cell TEXT NOT NULL,source_url TEXT NOT NULL,reason TEXT NOT NULL,
      PRIMARY KEY(batch,computer_id,slot));
CREATE TABLE publishing_layout_state(id BIGINT PRIMARY KEY CHECK(id=1),batch TEXT NOT NULL);
CREATE TABLE publishing_layout_links(
      batch TEXT NOT NULL,computer_id TEXT NOT NULL,slot BIGINT NOT NULL,
      previous_reason TEXT NOT NULL,actor_id BIGINT NOT NULL,updated_at BIGINT NOT NULL,
      PRIMARY KEY(batch,computer_id,slot),
      FOREIGN KEY(batch,computer_id,slot) REFERENCES publishing_layout(batch,computer_id,slot));
CREATE TABLE operations_history(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id TEXT NOT NULL,
      at BIGINT NOT NULL,actor_id BIGINT,actor_name TEXT NOT NULL,action TEXT NOT NULL,entity TEXT NOT NULL,
      before_json TEXT,after_json TEXT);
CREATE TABLE operations_previews(id TEXT PRIMARY KEY,actor_id BIGINT NOT NULL,
      expires_at BIGINT NOT NULL,kind TEXT NOT NULL,payload TEXT NOT NULL);
CREATE TABLE nurture_records(
      account_id TEXT PRIMARY KEY REFERENCES accounts(id),started_on TEXT NOT NULL DEFAULT '',
      completed_on TEXT NOT NULL DEFAULT '',cycle BIGINT NOT NULL DEFAULT 1,
      image_count BIGINT NOT NULL DEFAULT 0,revision BIGINT NOT NULL DEFAULT 0, verification_state TEXT NOT NULL DEFAULT '待检查', verification_owner TEXT NOT NULL DEFAULT '', verification_note TEXT NOT NULL DEFAULT '', verification_updated_on TEXT NOT NULL DEFAULT '', workflow TEXT NOT NULL DEFAULT '待开始', active_since TEXT NOT NULL DEFAULT '', banked_days BIGINT NOT NULL DEFAULT 0, paused_on TEXT NOT NULL DEFAULT '', periods TEXT NOT NULL DEFAULT '[]', legacy_started_on TEXT NOT NULL DEFAULT '');
CREATE TABLE nurture_images(id TEXT PRIMARY KEY,
      account_id TEXT NOT NULL REFERENCES accounts(id),cycle BIGINT NOT NULL,day TEXT NOT NULL,
      mime TEXT NOT NULL,content BYTEA NOT NULL,actor TEXT NOT NULL);
CREATE UNIQUE INDEX auth_single_owner ON auth_users(role) WHERE role='owner';
CREATE INDEX nurture_image_account ON nurture_images(account_id,cycle);
CREATE INDEX operations_history_entity ON operations_history(entity,id);
CREATE TABLE runtime_control(id BIGINT PRIMARY KEY CHECK(id=1), mode TEXT NOT NULL CHECK(mode IN ('maintenance','open')),writer_epoch BIGINT NOT NULL,restore_generation TEXT NOT NULL);
INSERT INTO runtime_control VALUES(1,'maintenance',1,'uninitialized');
